practice.code:
-- Query run thousands of times per minute:
SELECT id FROM orders
WHERE customer_id = ?
ORDER BY created_at;

CREATE INDEX idx_orders ON orders (created_at, customer_id);

discovery.code:
CREATE TABLE users (
  id bigint PRIMARY KEY,
  email text UNIQUE
);

practice.code:
-- The only query on this table (95% of users are active):
SELECT id, email FROM users
WHERE tenant_id = ? AND active = true;

CREATE INDEX idx_a ON users (active);
CREATE INDEX idx_b ON users (active, tenant_id);
